source='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    foregrounds = [color for color in counts if color != background]
    if not foregrounds:
        return out
    color = max(foregrounds, key=lambda c: counts[c])
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
    if not points:
        return out
    r0 = min(r for r, c in points); r1 = max(r for r, c in points)
    c0 = min(c for r, c in points); c1 = max(c for r, c in points)
    # Extend each substantial horizontal or vertical stroke across the object's bounds.
    for r in range(r0, r1 + 1):
        if sum(grid[r][c] == color for c in range(w)) >= 3:
            for c in range(c0, c1 + 1):
                if grid[r][c] != color:
                    out[r][c] = 2
    for c in range(c0, c1 + 1):
        if sum(grid[r][c] == color for r in range(h)) >= 3:
            for r in range(r0, r1 + 1):
                if grid[r][c] != color:
                    out[r][c] = 2
    return out
'''
